CREATE TABLE public.conversation_shortcuts (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL, conversation_id UUID NOT NULL, shortcut_id TEXT NOT NULL, last_published_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (user_id, conversation_id)); ALTER TABLE public.conversation_shortcuts ENABLE ROW LEVEL SECURITY; CREATE POLICY "sc_read_own" ON public.conversation_shortcuts FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "sc_insert_own" ON public.conversation_shortcuts FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "sc_update_own" ON public.conversation_shortcuts FOR UPDATE TO authenticated USING (auth.uid() = user_id); CREATE POLICY "sc_delete_own" ON public.conversation_shortcuts FOR DELETE TO authenticated USING (auth.uid() = user_id);